test("commas in any field keep four columns (CRM-284)",()=>{
  const csv=exportContacts([{id:"c3",name:"Doe, Jane",company:"Acme, Inc",email:"jane@example.test"}]);
  assert.equal(csv,"id,name,company,email\r\nc3,Doe; Jane,Acme; Inc,jane@example.test\r\n");
  for (const line of csv.split("\r\n").filter(Boolean)) assert.equal(line.split(",").length,4);
});
